import{_ as e,d as r,e as a,x as o}from"./chunks/framework.BRr8VP3a.js";const _=JSON.parse('{"title":"成功一次，为什么仍要分别问维持、恢复与复制","description":"四种结果各有条件；已有成效和新阶段失败可以同时成立。","frontmatter":{"title":"成功一次，为什么仍要分别问维持、恢复与复制","description":"四种结果各有条件；已有成效和新阶段失败可以同时成立。"},"headers":[],"relativePath":"concepts/four-outcomes.md","filePath":"concepts/four-outcomes.md"}'),d={name:"concepts/four-outcomes.md"};function s(c,t,p,h,n,i){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="成功一次-为什么仍要分别问维持、恢复与复制" tabindex="-1">成功一次，为什么仍要分别问维持、恢复与复制 <a class="header-anchor" href="#成功一次-为什么仍要分别问维持、恢复与复制" aria-label="Permalink to &quot;成功一次，为什么仍要分别问维持、恢复与复制&quot;">​</a></h1><p>四种结果各有条件；已有成效和新阶段失败可以同时成立。</p><p>安排建立了、现在运转良好、故障后恢复了、换一个地方也做成了，分别是形成、维持、恢复和复制。v2的<a href="./../theory/part-06.html#section-6-10-1">§6.10.1</a>要求逐项判断。</p><div class="xk-table"><table><thead><tr><th>结果</th><th>继续检查什么</th></tr></thead><tbody><tr><td>形成</td><td>启动条件及从原状态过渡的路径</td></tr><tr><td>维持</td><td>持续补给、替换与校正</td></tr><tr><td>恢复</td><td>受扰后仍可调用的载体、余量、外援与时间</td></tr><tr><td>复制</td><td>新对象、地点或规模自己的人员、设备、时间和纠错条件</td></tr></tbody></table></div><p>原处成功，对新地点只提供候选。复制或扩大失败时，至少比较四条解释：原方案无效；未按事前内容实施；缺少事前声明的使能条件；规模变化改变了处理或对象。它们需要区分性材料，不是四个可任选的免责理由。</p><p>教学情景：试点时有培训和权限，扩展时没有落实。若这些要求在结果前已声明，可以检查实施缺口；若失败后才追加“还必须由创始人每天在场”，它只能作为下一轮候选。结果后取得的记录仍可用于核实事前声明的条件，关键不在取证日期本身。</p><p><a href="./../cases/gitlab-recovery.html">GitLab恢复案例</a>可以帮助读者区分功能恢复与未来恢复能力。案例原有事实和截止日期保持不变，它不因此成为本节全部机制的检验。需要支持的真实恢复也不用靠撤掉支持来证明。</p><p>继续阅读：<a href="./recovery.html">支持与恢复</a>、<a href="./../theory/part-06.html#section-6-5">§6.5维护</a>、<a href="./../theory/part-06.html#section-6-10">§6.10修复边界</a>。</p>',8)])])}const m=e(d,[["render",s]]);export{_ as __pageData,m as default};
